        try container.encode(lastStateTransitionDate, forKey: .lastStateTransitionDate)
        try container.encode(coverageIdentifiers, forKey: .coverageIdentifiers)
        try container.encode(totalDidacticHours, forKey: .totalDidacticHours)
        try container.encode(totalOtherHours, forKey: .totalOtherHours)
        try container.encode(logistics, forKey: .logistics)
        try container.encode(activity, forKey: .activity)
    }
}

public struct Esse3TeacherDiaryNotes: Codable, Hashable, Sendable {
    /// id della nota del diario
    public var diaryNoteId: Int64
    /// nota del docente sul diario
    public var note: String?

    public init(
        diaryNoteId: Int64 = 0,
        note: String? = nil
    ) {
        self.diaryNoteId = diaryNoteId
        self.note = note
    }

    private enum CodingKeys: String, CodingKey {
        case diaryNoteId = "notaDiarioId"
        case note = "nota"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.diaryNoteId = container.decodeLenient(Int64.self, forKey: .diaryNoteId) ?? 0
        self.note = container.decodeLenient(String.self, forKey: .note)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(diaryNoteId, forKey: .diaryNoteId)
        try container.encode(note, forKey: .note)
    }
}
